source='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    regions = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 0 and (yy,xx) not in seen:
                        seen.add((yy,xx))
                        stack.append((yy,xx))
            regions.append((min(y for y,x in cells), max(y for y,x in cells),
                            min(x for y,x in cells), max(x for y,x in cells)))
    for r0, r1, c0, c1 in regions:
        colors = {grid[r][c] for r in range(r0,r1+1) for c in range(c0,c1+1) if grid[r][c] not in (0,8)}
        if len(colors) != 1:
            continue
        color = next(iter(colors))
        points = [(r,c) for r in range(r0,r1+1) for c in range(c0,c1+1) if grid[r][c] == color]
        pr0, pr1 = min(r for r,c in points), max(r for r,c in points)
        pc0, pc1 = min(c for r,c in points), max(c for r,c in points)
        pattern = [[grid[r][c] for c in range(pc0,pc1+1)] for r in range(pr0,pr1+1)]
        ph, pw = len(pattern), len(pattern[0])
        for r in range(r0,r1+1):
            for c in range(c0,c1+1):
                out[r][c] = pattern[(r-pr0)%ph][(c-pc0)%pw]
    return out
'''
